use super::*;
/// 📦️ Physical fixed source frames preserve u64 identities and optional-empty extents without heap effects.
#[test]
fn original_source_frame_matches_portable_bytes_without_heap(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let value=&row["source"];let array=|name:&str|value[name].as_array().map(|bytes|bytes.iter().map(|byte|byte.as_u64().unwrap()as u8).collect());let source=OriginalJobSource{job:value["job"].as_str().unwrap().parse().unwrap(),kind:value["kind"].as_str().unwrap().to_owned(),input:array("input"),checkpoint:array("checkpoint")};let expected=row["hex"].as_str().unwrap().as_bytes().chunks_exact(2).map(|bytes|u8::from_str_radix(std::str::from_utf8(bytes).unwrap(),16).unwrap()).collect::<std::vec::Vec<_>>();let(header,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalJobSourceWireHeader::from_source(&source));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));let(bytes,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||header.bytes());assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(&bytes[..],&expected[..40]);let(decoded,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalJobSourceWireHeader::read(&bytes,expected.len()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(decoded.unwrap(),header);assert_eq!(header.extent().unwrap(),expected.len());for(field,body)in [(0,Some(source.kind.as_bytes())),(1,source.input.as_deref()),(2,source.checkpoint.as_deref())]{assert_eq!(header.field_range(field).unwrap().map(|(offset,length)|&expected[offset..offset+length]),body);}for(index,value)in[(0,0),(4,4),(5,1),(6,1),(7,1)]{let mut invalid=bytes;invalid[index]=value;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||OriginalJobSourceWireHeader::read(&invalid,expected.len()));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(result.is_err());}assert!(OriginalJobSourceWireHeader::read(&bytes[..39],expected.len()).is_err());assert!(OriginalJobSourceWireHeader::read(&bytes,expected.len()+1).is_err());}
 println!("[DEBUG] Original source40 compact metadata exact portable Unicode/u64max/optional-empty ranges, six malformed cuts percase; actual metadata heap0/0");
}
